                "operationId": "update-unit-group",
                "summary": "Update Unit Group",
                "description": "Partially updates a unit group. System unit groups cannot be updated.\n\nThis endpoint requires the permission: `unit_groups:update`.",
                "method": "PATCH",
                "path": "/v1/catalog/unit-groups/{id}",
                "domain": "catalog",
