                "summary": "Hide Conversation",
                "description": "Hides a conversation from the caller's own list without affecting other participants.\n\nThis endpoint requires the permission: `messaging:update`.",
                "method": "POST",
                "path": "/v1/messaging/conversations/{id}/actions/hide",
                "domain": "messaging",
                "tag": "Conversations",
