                "operationId": "update-part",
                "summary": "Update Part",
                "description": "Partially updates a part.\n\nFields not provided retain their current values.\n\nThis endpoint requires the permissions: `parts:update`, `customers:update`, `suppliers:update`.",
                "method": "PATCH",
                "path": "/v1/catalog/parts/{id}",
                "domain": "catalog",
