                "operationId": "retrieve-product",
                "summary": "Retrieve Product",
                "description": "Returns a product by ID.\n\nThis endpoint requires the permissions: `items:read`, `customers:read`, `suppliers:read`.",
                "method": "GET",
                "path": "/v1/catalog/products/{id}",
                "domain": "catalog",
